<script setup lang="ts">import { computed } from 'vue'; import { formatMoney } from '../../utils/formatters'; const props = defineProps<{ items: Array<{ label: string; total: string }> }>(); const maximum = computed(() => Math.max(1, ...props.items.map((item) => Number(item.total))));</script>
<template><div class="space-y-3"><div v-for="item in items" :key="item.label" class="grid grid-cols-[7rem_1fr_auto] items-center gap-3 text-sm"><span class="truncate">{{ item.label }}</span><div class="h-3 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full bg-brand-500" :style="{ width: `${Math.max(2, Number(item.total) / maximum * 100)}%` }" /></div><span class="tabular-nums">{{ formatMoney(item.total) }}</span></div></div></template>
